package com.yonlab.vision;
import org.junit.Test;import static org.junit.Assert.*;import java.util.*;import java.io.*;import java.lang.reflect.*;import java.nio.*;import java.nio.file.*;
public final class SoundMathTest {
 @Test public void sameWindowsForShortAndTailInputs(){assertArrayEquals(new int[]{0},SoundMath.starts(1));assertArrayEquals(new int[]{0},SoundMath.starts(15600));assertArrayEquals(new int[]{0,7680},SoundMath.starts(15601));assertEquals(10,SoundMath.starts(80000).length);assertEquals(69120,SoundMath.starts(80000)[9]);}
 @Test public void windowsNeverDiscardTail(){for(int length:new int[]{1,15600,15601,23280,80000,480000}){int[] starts=SoundMath.starts(length);assertTrue(starts[starts.length-1]+15600>=length);assertTrue(starts[starts.length-1]<length);}}
 @Test public void finalWindowPadsOnlyMissingSamples(){float[] pcm={.3f,-.5f,.9f};float[] result=SoundMath.window(pcm,1);assertEquals(-.5f,result[0],0);assertEquals(.9f,result[1],0);assertEquals(0,result[2],0);assertEquals(15600,result.length);}
 @Test(expected=IllegalArgumentException.class)public void rejectOverThirtySeconds(){SoundMath.starts(480001);}
 @Test(expected=IllegalArgumentException.class)public void rejectEmpty(){SoundMath.starts(0);}
 @Test public void stableScoreRankingDoesNotCrossCompareModels(){assertArrayEquals(new int[]{1,2,0},SoundMath.top(new float[]{.1f,.9f,.9f},3));}
 @Test(expected=IllegalArgumentException.class)public void rejectNonfiniteModelScores(){SoundMath.top(new float[]{Float.NaN},1);}
 @Test public void resamplingKeepsDurationAndDcLevel()throws Exception{float[] source=new float[44100];Arrays.fill(source,.25f);float[] result=SoundMath.resample(source,44100,()->false);assertEquals(16000,result.length);for(int i=0;i<result.length;i++)assertEquals(.25f,result[i],.00001f);}
 @Test public void nativePcmDoesNotAliasMutableSource()throws Exception{float[] source={.1f,.2f};float[] result=SoundMath.resample(source,16000,()->false);source[0]=.9f;assertEquals(.1f,result[0],0);}
 @Test public void downsamplingAttenuatesAboveNyquist()throws Exception{double good=energy(tone(1000)),alias=energy(tone(11000));assertTrue("wanted tone retained",good>.3);assertTrue("ultrasonic alias rejected",alias<good*.08);}
 private static float[] tone(int hz)throws Exception{float[] input=new float[44100];for(int i=0;i<input.length;i++)input[i]=(float)Math.sin(2*Math.PI*hz*i/44100);return SoundMath.resample(input,44100,()->false);}
 private static double energy(float[] input){double sum=0;for(int i=200;i<input.length-200;i++)sum+=input[i]*input[i];return Math.sqrt(sum/(input.length-400));}
 @Test(expected=InterruptedIOException.class)public void cancellationInterruptsLongResample()throws Exception{SoundMath.resample(new float[44100],44100,()->true);}
 @Test(expected=IOException.class)public void resampleRejectsTooLongInput()throws Exception{SoundMath.resample(new float[4001*30],4000,()->false);}
 @Test public void quotedClassMapLabelsRetainCommas(){assertArrayEquals(new String[]{"94","/m/x","Chicken, rooster"},SoundMath.csv("94,/m/x,\"Chicken, rooster\""));assertArrayEquals(new String[]{"a\"b","c"},SoundMath.csv("\"a\"\"b\",c"));}
 @Test public void waveformIncludesTransientPeaks(){assertArrayEquals(new float[]{.9f,.7f},SoundMath.waveform(new float[]{.1f,-.9f,-.7f,.2f},2),0);}
 @Test public void pcmHashIsStableAndSignSensitive()throws Exception{assertEquals(SoundMath.pcmSha(new float[]{.1f,-.2f}),SoundMath.pcmSha(new float[]{.1f,-.2f}));assertNotEquals(SoundMath.pcmSha(new float[]{.1f,-.2f}),SoundMath.pcmSha(new float[]{.1f,.2f}));}
 @Test public void stereoWavDownmixAndRateAreReadFromActualBytes()throws Exception{Path path=fixture(44100,2,16,new short[]{16384,0,0,-16384});Object input=owner(path);Method method=SoundAudioInput.class.getDeclaredMethod("wave",SoundMath.Cancel.class);method.setAccessible(true);float[] values=(float[])method.invoke(input,(SoundMath.Cancel)()->false);assertArrayEquals(new float[]{.25f,-.25f},values,0);assertEquals(44100,((SoundAudioInput)input).sourceRate);assertEquals(2,((SoundAudioInput)input).sourceChannels);Files.delete(path);}
 @Test public void malformedWavDoesNotBecomeSilentSuccess()throws Exception{Path path=fixture(16000,1,16,new short[]{100});byte[] raw=Files.readAllBytes(path);raw[40]=(byte)100;Files.write(path,raw);Method method=SoundAudioInput.class.getDeclaredMethod("wave",SoundMath.Cancel.class);method.setAccessible(true);try{method.invoke(owner(path),(SoundMath.Cancel)()->false);fail("truncated data accepted");}catch(InvocationTargetException e){assertTrue(e.getCause() instanceof IOException);}finally{Files.delete(path);}}
 private static Object owner(Path path)throws Exception{Constructor<SoundAudioInput> constructor=SoundAudioInput.class.getDeclaredConstructor(File.class);constructor.setAccessible(true);return constructor.newInstance(path.toFile());}
 private static Path fixture(int rate,int channels,int bits,short[] values)throws Exception{Path root=Paths.get(System.getProperty("sound.test.root", "build/tmp/sound-tests"));Files.createDirectories(root);Path path=Files.createTempFile(root,"sound-test-",".wav");ByteBuffer b=ByteBuffer.allocate(44+values.length*2).order(ByteOrder.LITTLE_ENDIAN);b.put(new byte[]{'R','I','F','F'}).putInt(36+values.length*2).put(new byte[]{'W','A','V','E','f','m','t',' '}).putInt(16).putShort((short)1).putShort((short)channels).putInt(rate).putInt(rate*channels*bits/8).putShort((short)(channels*bits/8)).putShort((short)bits).put(new byte[]{'d','a','t','a'}).putInt(values.length*2);for(short v:values)b.putShort(v);Files.write(path,b.array());return path;}
}
